from __future__ import annotations

import argparse
import json
import traceback
from typing import Any

import torch

OP_NAME = 'unknown_op'
ERROR_TYPE = ''


def _resolve_op(op_name: str) -> Any:
    parts = op_name.split('.')
    if len(parts) < 2:
        raise ValueError(f'expected namespace.op[.overload], got {op_name!r}')
    namespace, op = parts[0], parts[1]
    overload = parts[2] if len(parts) > 2 else 'default'
    packet = getattr(getattr(torch.ops, namespace), op)
    if overload in {'', 'default'}:
        return packet.default if hasattr(packet, 'default') else packet
    return getattr(packet, overload)


def _sample_inputs(op_name: str) -> tuple[Any, ...]:
    name = op_name.lower()
    if 'matmul' in name or name.endswith('.mm.default'):
        return (torch.randn(2, 3), torch.randn(3, 4))
    if 'linear' in name:
        return (torch.randn(2, 3), torch.randn(4, 3), torch.randn(4))
    if any(key in name for key in ('add', 'sub', 'mul', 'div')):
        return (torch.randn(2, 3), torch.randn(2, 3))
    if 'mean' in name or 'sum' in name:
        return (torch.randn(2, 3),)
    if 'conv2d' in name or 'convolution' in name:
        return (torch.randn(1, 3, 8, 8), torch.randn(4, 3, 3, 3), None, [1, 1], [1, 1], [1, 1], False, [0, 0], 1)
    if any(key in name for key in ('relu', 'gelu', 'sigmoid', 'tanh', 'exp', 'log', 'sqrt', 'neg', 'abs', 'sin', 'cos', 'erf', 'silu')):
        return (torch.randn(2, 3),)
    return (torch.randn(2, 3),)


def _clone_arg(arg: Any) -> Any:
    if isinstance(arg, torch.Tensor):
        return arg.detach().clone().requires_grad_(arg.is_floating_point())
    if isinstance(arg, list):
        return list(arg)
    return arg


def _summarize(value: Any) -> Any:
    if isinstance(value, torch.Tensor):
        return {'shape': list(value.shape), 'dtype': str(value.dtype), 'sum': float(value.detach().float().sum().item())}
    if isinstance(value, (tuple, list)):
        return [_summarize(x) for x in value]
    return repr(value)


def _run_torch(op: Any, inputs: tuple[Any, ...]) -> Any:
    return op(*[_clone_arg(x) for x in inputs])


def _run_torch4ms(op: Any, inputs: tuple[Any, ...]) -> Any:
    import torch4ms

    env = torch4ms.default_env()
    with env:
        return op(*[_clone_arg(x) for x in inputs])


def _run_torch4ms_summary(op: Any, inputs: tuple[Any, ...]) -> Any:
    import torch4ms

    env = torch4ms.default_env()
    with env:
        return _summarize(op(*[_clone_arg(x) for x in inputs]))


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description='Minimal torch/torch4ms core operator repro')
    parser.add_argument('--mode', choices=['torch', 'torch4ms', 'both'], default='both')
    args = parser.parse_args(argv)
    report: dict[str, Any] = {'op_name': OP_NAME, 'error_type': ERROR_TYPE, 'mode': args.mode}
    failed = False
    try:
        op = _resolve_op(OP_NAME)
        inputs = _sample_inputs(OP_NAME)
    except Exception as exc:
        report['resolve'] = {'ok': False, 'type': type(exc).__name__, 'message': str(exc), 'traceback': traceback.format_exc()[-4000:]}
        print(json.dumps(report, indent=2, ensure_ascii=False))
        return 1
    if args.mode in {'torch', 'both'}:
        try:
            report['torch'] = {'ok': True, 'output': _summarize(_run_torch(op, inputs))}
        except Exception as exc:
            failed = True
            report['torch'] = {'ok': False, 'type': type(exc).__name__, 'message': str(exc), 'traceback': traceback.format_exc()[-4000:]}
    if args.mode in {'torch4ms', 'both'}:
        try:
            report['torch4ms'] = {'ok': True, 'output': _run_torch4ms_summary(op, inputs)}
        except Exception as exc:
            failed = True
            report['torch4ms'] = {'ok': False, 'type': type(exc).__name__, 'message': str(exc), 'traceback': traceback.format_exc()[-4000:]}
    print(json.dumps(report, indent=2, ensure_ascii=False))
    return 1 if failed else 0


if __name__ == '__main__':
    raise SystemExit(main())
